if (forkshell(jp, lp->n, n->npipe.backgnd) == 0) {
        INTON;
        if (prevfd > 0) {
                dup2(prevfd, 0);
                close(prevfd);
        }
        if (pip[1] >= 0) {
                if (!(prevfd >= 0 && pip[0] == 0))
                        close(pip[0]);
                if (pip[1] != 1) {
                        dup2(pip[1], 1);
                        close(pip[1]);
                }
        }
        evaltree(lp->n, EV_EXIT);
